def rotate_items(items, k):
    if not items:
        return ()
    k %= len(items)
    return tuple(items[-k:] + items[:-k]) if k else tuple(items)

def interleave(left, right):
    for left_item, right_item in zip(left, right):
        yield left_item
        yield right_item

def find_products(products, query):
    return tuple(
        sorted(
            (product for product in products if query in product["name"]),
            key=lambda product: product["score"],
            reverse=True,
        )
    )

def group_words(words):
    groups = {}
    for word in words:
        groups.setdefault(word[0], []).append(word)
    if not groups:
        return None
    return tuple((initial, tuple(group)) for initial, group in groups.items())

def nearest_date(dates, target):
    from datetime import date

    if not dates:
        return None

    target_date = date.fromisoformat(target)
    return min(
        dates,
        key=lambda value: abs((date.fromisoformat(value) - target_date).days),
    )

def median_value(values):
    ordered = sorted(values)
    count = len(ordered)
    if count == 0:
        return None
    middle = count // 2
    if count % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2

def merge_ranges(ranges):
    merged = []
    for start, end in sorted(ranges, key=lambda interval: interval[0]):
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

def shortest_path(graph, start, goal):
    if start == goal:
        return (start,)

    queue = [start]
    predecessors = {start: None}
    index = 0

    while index < len(queue):
        node = queue[index]
        index += 1

        for neighbor in graph.get(node, ()):
            if neighbor in predecessors:
                continue

            predecessors[neighbor] = node
            if neighbor == goal:
                path = [goal]
                current = goal
                while current != start:
                    current = predecessors[current]
                    path.append(current)
                return tuple(reversed(path))

            queue.append(neighbor)

    return None

def topological_order(nodes, edges):
    from heapq import heappop, heappush

    node_order = tuple(nodes)
    position = {node: index for index, node in enumerate(node_order)}
    adjacency = {node: [] for node in node_order}
    indegree = {node: 0 for node in node_order}

    for source, destination in edges:
        adjacency[source].append(destination)
        indegree[destination] += 1

    ready = []
    for node in node_order:
        if indegree[node] == 0:
            heappush(ready, (position[node], node))

    result = []
    while ready:
        _, node = heappop(ready)
        result.append(node)
        for destination in adjacency[node]:
            indegree[destination] -= 1
            if indegree[destination] == 0:
                heappush(ready, (position[destination], destination))

    return tuple(result)
